#!/usr/bin/env sh
# Enforce Conventional Commits on the first line (CLAUDE.md, "Git and GitHub workflow").
set -eu

first_line=$(head -n 1 "$1")

# Merge and revert commits generated by git are allowed as-is.
case "$first_line" in
  Merge\ *|Revert\ *) exit 0 ;;
esac

pattern='^(feat|fix|chore|docs|refactor|test|perf|build|ci|style|revert)(\([a-z0-9/.-]+\))?!?: .{1,100}$'
if ! printf '%s\n' "$first_line" | grep -Eq "$pattern"; then
  echo "Commit message must follow Conventional Commits, for example 'feat(agent): add operation journal'." >&2
  echo "Got: $first_line" >&2
  exit 1
fi
